___CSS_LOADER_EXPORT___.push([module.id, `.table-container {
  position: relative;
  width: 100%;
}

.spinner-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: rgba(255, 255, 255, 0.8);
  z-index: 10;
}

table {
  width: 100%;
  border-collapse: collapse;
  box-shadow: none;
}
table tr {
  transition: background-color 0.2s ease-in-out;
  cursor: pointer;
  height: 30px;
}
table tr:hover {
  background-color: #ebedf3;
}
table tr.selected-row {
  background-color: #ddeefc !important;
}

.mat-header-cell,
.mat-cell {
  text-align: left;
  padding: 8px;
}

.no-columns-message {
  text-align: center;
  color: red;
  font-weight: bold;
  margin: 20px;
}`, ""]);
